import { FormEvent, useMemo, useState } from 'react';
import { CalendarDays, Clock, Users, Pencil, X, CheckCircle2 } from 'lucide-react';
import clsx from 'clsx';
import confetti from 'canvas-confetti';
import type { Route } from '../App';
import { IMG } from '../data/images';
import { longDate, slotsFor, todayISO, uid, usePersisted } from '../lib/utils';

type Zone = 'Sala' | 'Barra de métodos' | 'Terraza';
type Booking = { id: string; name: string; phone: string; email: string; date: string; time: string; people: number; zone: Zone; notes: string };
type Draft = Omit<Booking, 'id'>;

const ZONES: { id: Zone; hint: string }[] = [
  { id: 'Sala', hint: 'Mesas junto al ventanal' },
  { id: 'Barra de métodos', hint: 'Ves preparar tu filtro' },
  { id: 'Terraza', hint: 'Cubierta, admite perros' },
];
const EMPTY: Draft = { name: '', phone: '', email: '', date: todayISO(1), time: '10:00', people: 2, zone: 'Sala', notes: '' };
const SEED: Booking[] = [{ id: 'TN-4K8Q', name: 'Ane Uribe', phone: '612 448 093', email: 'ane@correo.es', date: todayISO(3), time: '10:30', people: 2, zone: 'Barra de métodos', notes: 'Queremos probar la cata de tres orígenes.' }];

function validate(d: Draft) {
  const e: Partial<Record<keyof Draft, string>> = {};
  if (d.name.trim().length < 2) e.name = 'Indica a nombre de quién reservamos.';
  if (!/^[6-9]\d{8}$/.test(d.phone.replace(/\s/g, ''))) e.phone = 'Un teléfono español de 9 cifras, p. ej. 612 345 678.';
  if (!/^\S+@\S+\.\S+$/.test(d.email)) e.email = 'Revisa el correo; ahí te llega la confirmación.';
  if (!d.date || d.date < todayISO()) e.date = 'Elige hoy o una fecha futura.';
  else if (d.date > todayISO(60)) e.date = 'Abrimos reservas con 60 días de antelación como máximo.';
  if (!slotsFor(d.date).includes(d.time)) e.time = 'Elige una hora dentro del horario de ese día.';
  if (d.people < 1 || d.people > 8) e.people = 'Para grupos de más de 8, escríbenos a hola@tuestenorte.es.';
  return e;
}

export default function Reservations({ go }: { go: (r: Route) => void }) {
  const [bookings, setBookings] = usePersisted<Booking[]>('reservas', SEED);
  const [draft, setDraft] = useState<Draft>(EMPTY);
  const [errors, setErrors] = useState<Partial<Record<keyof Draft, string>>>({});
  const [editing, setEditing] = useState<string | null>(null);
  const [done, setDone] = useState<Booking | null>(null);
  const [cancelId, setCancelId] = useState<string | null>(null);
  const slots = useMemo(() => slotsFor(draft.date), [draft.date]);

  const set = <K extends keyof Draft>(k: K, v: Draft[K]) => {
    setDraft((d) => {
      const next = { ...d, [k]: v };
      if (k === 'date' && !slotsFor(next.date).includes(next.time)) next.time = slotsFor(next.date)[2] ?? '';
      return next;
    });
    if (errors[k]) setErrors((e) => ({ ...e, [k]: undefined }));
  };

  const submit = (ev: FormEvent) => {
    ev.preventDefault();
    const e = validate(draft);
    setErrors(e);
    if (Object.keys(e).length) return;
    const booking: Booking = { ...draft, name: draft.name.trim(), id: editing ?? `TN-${uid().slice(0, 4)}` };
    setBookings((p) => (editing ? p.map((b) => (b.id === editing ? booking : b)) : [booking, ...p]));
    setDone(booking);
    setEditing(null);
    setDraft(EMPTY);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    confetti({ particleCount: 80, spread: 65, origin: { y: 0.35 }, colors: ['#21402F', '#9A2E3D', '#E7B98F', '#F0F1EC'] });
  };

  const edit = (b: Booking) => {
    const { id, ...rest } = b;
    setDraft(rest); setEditing(id); setDone(null); setErrors({});
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const err = (k: keyof Draft) => errors[k] && <span className="mt-1 block text-sm font-medium text-[#9A2E3D]">{errors[k]}</span>;
  const upcoming = [...bookings].filter((b) => b.date >= todayISO()).sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));

  return (
    <div className="anim-fade mx-auto grid max-w-[1200px] gap-10 px-5 pb-20 pt-12 md:px-8 lg:grid-cols-[1.25fr_1fr] lg:gap-14">
      <div>
        <h1 className="display text-[2.5rem] leading-[1.08] sm:text-[3.2rem]">{editing ? 'Modificar reserva' : 'Reserva tu mesa'}</h1>
        <p className="mt-4 max-w-lg text-lg text-[#1C2326]/75">Guardamos la mesa 15 minutos. Sin reserva también eres bienvenido: dejamos la mitad de la sala libre.</p>

        {done ? (
          <div className="anim-pop mt-8 rounded-[22px] bg-[#21402F] p-7 text-[#F0F1EC]">
            <CheckCircle2 size={32} className="text-[#A9CBB7]" />
            <p className="display mt-3 text-[1.9rem]">¡Mesa reservada, {done.name.split(' ')[0]}!</p>
            <p className="mt-2 text-[#F0F1EC]/80">Código <strong className="text-white">{done.id}</strong>. Te hemos enviado la confirmación a {done.email}.</p>
            <ul className="mt-5 grid gap-2 sm:grid-cols-3">
              <li className="flex items-center gap-2"><CalendarDays size={17} />{longDate(done.date)}</li>
              <li className="flex items-center gap-2"><Clock size={17} />{done.time} h</li>
              <li className="flex items-center gap-2"><Users size={17} />{done.people} {done.people === 1 ? 'persona' : 'personas'} · {done.zone}</li>
            </ul>
            <div className="mt-6 flex flex-wrap gap-3">
              <button className="btn bg-[#F0F1EC] text-[#21402F]" onClick={() => setDone(null)}>Hacer otra reserva</button>
              <button className="btn btn-ghost" onClick={() => go('inicio')}>Volver al inicio</button>
            </div>
          </div>
        ) : (
          <form onSubmit={submit} noValidate className="mt-8 grid gap-5 rounded-[22px] border border-[#1C2326]/10 bg-[#FBFBF8] p-6 sm:grid-cols-2 sm:p-7">
            <label className="text-sm font-medium sm:col-span-2">Nombre
              <input className={clsx('field mt-1.5', errors.name && 'err')} value={draft.name} onChange={(e) => set('name', e.target.value)} placeholder="Nombre y apellido" autoComplete="name" />{err('name')}
            </label>
            <label className="text-sm font-medium">Teléfono
              <input className={clsx('field mt-1.5', errors.phone && 'err')} value={draft.phone} onChange={(e) => set('phone', e.target.value)} placeholder="612 345 678" inputMode="tel" autoComplete="tel" />{err('phone')}
            </label>
            <label className="text-sm font-medium">Correo
              <input className={clsx('field mt-1.5', errors.email && 'err')} value={draft.email} onChange={(e) => set('email', e.target.value)} placeholder="tu@correo.es" type="email" autoComplete="email" />{err('email')}
            </label>
            <label className="text-sm font-medium">Día
              <input type="date" min={todayISO()} className={clsx('field mt-1.5', errors.date && 'err')} value={draft.date} onChange={(e) => set('date', e.target.value)} />{err('date')}
            </label>
            <label className="text-sm font-medium">Hora
              <select className={clsx('field mt-1.5', errors.time && 'err')} value={draft.time} onChange={(e) => set('time', e.target.value)}>
                {slots.length === 0 && <option value="">Elige primero el día</option>}
                {slots.map((s) => <option key={s}>{s}</option>)}
              </select>{err('time')}
            </label>
            <div className="text-sm font-medium sm:col-span-2">Personas
              <div className="mt-1.5 flex flex-wrap gap-2" role="group" aria-label="Número de personas">
                {[1, 2, 3, 4, 5, 6, 7, 8].map((n) => (
                  <button type="button" key={n} onClick={() => set('people', n)} aria-pressed={draft.people === n}
                    className={clsx('h-11 w-11 rounded-full border text-base font-semibold transition-colors',
                      draft.people === n ? 'border-[#21402F] bg-[#21402F] text-[#F0F1EC]' : 'border-[#1C2326]/20 hover:border-[#21402F]')}>{n}</button>
                ))}
              </div>{err('people')}
            </div>
            <div className="text-sm font-medium sm:col-span-2">Zona
              <div className="mt-1.5 grid gap-2 sm:grid-cols-3" role="radiogroup" aria-label="Zona">
                {ZONES.map((z) => (
                  <button type="button" role="radio" aria-checked={draft.zone === z.id} key={z.id} onClick={() => set('zone', z.id)}
                    className={clsx('rounded-2xl border p-3 text-left transition-colors', draft.zone === z.id ? 'border-[#21402F] bg-[#21402F]/[0.07] ring-1 ring-[#21402F]' : 'border-[#1C2326]/15 hover:border-[#21402F]/60')}>
                    <span className="block font-semibold">{z.id}</span>
                    <span className="text-[#1C2326]/60">{z.hint}</span>
                  </button>
                ))}
              </div>
            </div>
            <label className="text-sm font-medium sm:col-span-2">Comentarios <span className="font-normal text-[#1C2326]/55">(opcional)</span>
              <textarea className="field mt-1.5 min-h-[84px]" value={draft.notes} onChange={(e) => set('notes', e.target.value)} placeholder="Alergias, silla para bebé, una ocasión especial…" />
            </label>
            <div className="flex flex-wrap gap-3 sm:col-span-2">
              <button type="submit" className="btn btn-accent">{editing ? 'Guardar cambios' : 'Confirmar reserva'}</button>
              {editing && <button type="button" className="btn btn-ghost" onClick={() => { setEditing(null); setDraft(EMPTY); setErrors({}); }}>Descartar cambios</button>}
            </div>
          </form>
        )}
      </div>

      <aside className="space-y-6">
        <img src={IMG('cafe-granos')} alt="Dos personas brindando con sus lattes en una mesa" className="img-bg hidden h-[260px] w-full rounded-[22px] object-cover lg:block" />
        <div className="rounded-[22px] bg-[#E2DDD1] p-6">
          <h2 className="display text-[1.6rem]">Tus reservas</h2>
          {upcoming.length === 0 ? (
            <p className="mt-3 text-[#1C2326]/70">No tienes reservas próximas. Cuando confirmes una, aparecerá aquí para que puedas cambiarla o cancelarla.</p>
          ) : (
            <ul className="mt-4 space-y-3">
              {upcoming.map((b) => (
                <li key={b.id} className={clsx('rounded-2xl bg-[#FBFBF8] p-4', editing === b.id && 'ring-2 ring-[#9A2E3D]')}>
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="font-semibold first-letter:uppercase">{longDate(b.date)} · {b.time} h</p>
                      <p className="text-sm text-[#1C2326]/65">{b.people} {b.people === 1 ? 'persona' : 'personas'} · {b.zone} · {b.id}</p>
                    </div>
                    <div className="flex shrink-0 gap-1">
                      <button onClick={() => edit(b)} aria-label={`Modificar reserva ${b.id}`} className="grid h-9 w-9 place-items-center rounded-full hover:bg-[#21402F]/10"><Pencil size={16} /></button>
                      <button onClick={() => setCancelId(b.id)} aria-label={`Cancelar reserva ${b.id}`} className="grid h-9 w-9 place-items-center rounded-full hover:bg-[#9A2E3D]/10 hover:text-[#9A2E3D]"><X size={17} /></button>
                    </div>
                  </div>
                  {cancelId === b.id && (
                    <div className="anim-fade mt-3 flex flex-wrap items-center gap-3 border-t border-[#1C2326]/10 pt-3 text-sm">
                      <span>¿Cancelar esta reserva?</span>
                      <button className="font-semibold text-[#9A2E3D] hover:underline" onClick={() => { setBookings((p) => p.filter((x) => x.id !== b.id)); setCancelId(null); if (editing === b.id) { setEditing(null); setDraft(EMPTY); } }}>Sí, cancelar</button>
                      <button className="hover:underline" onClick={() => setCancelId(null)}>Mantenerla</button>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
        <p className="px-1 text-sm leading-relaxed text-[#1C2326]/65">Si llegas tarde o necesitas cambiar algo el mismo día, llámanos al 944 152 380.</p>
      </aside>
    </div>
  );
}

import { FormEvent, useState } from 'react';
import { Star, Trash2 } from 'lucide-react';
import clsx from 'clsx';
import { IMG } from '../data/images';
import { Review, SEED_REVIEWS } from '../data/cafe';
import { daysAgoText, usePersisted } from '../lib/utils';

type Stored = Review & { at: number; mine?: boolean };
const DAY = 86_400_000;

function Stars({ value, size = 16 }: { value: number; size?: number }) {
  return (
    <span className="inline-flex gap-0.5" aria-label={`${value} de 5 estrellas`}>
      {[1, 2, 3, 4, 5].map((i) => (
        <Star key={i} size={size} className={i <= value ? 'fill-[#9A2E3D] text-[#9A2E3D]' : 'text-[#1C2326]/25'} />
      ))}
    </span>
  );
}

export default function Reviews() {
  const [reviews, setReviews] = usePersisted<Stored[]>('reseñas', () => SEED_REVIEWS.map((r) => ({ ...r, at: Date.now() - r.daysAgo * DAY })));
  const [writing, setWriting] = useState(false);
  const [name, setName] = useState('');
  const [text, setText] = useState('');
  const [rating, setRating] = useState(5);
  const [error, setError] = useState('');

  const avg = reviews.reduce((s, r) => s + r.rating, 0) / Math.max(reviews.length, 1);
  const total = 308 + reviews.length;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (name.trim().length < 2) return setError('Escribe tu nombre para firmar la reseña.');
    if (text.trim().length < 20) return setError('Cuéntanos un poco más: al menos 20 caracteres.');
    setReviews((p) => [{ id: `r${Date.now()}`, name: name.trim(), rating, text: text.trim(), daysAgo: 0, at: Date.now(), mine: true }, ...p]);
    setName(''); setText(''); setRating(5); setError(''); setWriting(false);
  };

  return (
    <section id="resenas" className="mx-auto max-w-[1200px] px-5 py-20 md:px-8">
      <div className="flex flex-col justify-between gap-6 md:flex-row md:items-end">
        <div>
          <h2 className="display text-[2.2rem] leading-tight sm:text-[2.8rem]">Lo que dicen en la barra</h2>
          <p className="mt-3 flex items-center gap-3 text-[#1C2326]/70">
            <span className="display text-3xl text-[#1C2326]">{avg.toFixed(1).replace('.', ',')}</span>
            <Stars value={Math.round(avg)} size={18} />
            <span>{total} reseñas</span>
          </p>
        </div>
        <button onClick={() => setWriting((w) => !w)} className="btn btn-ghost self-start text-[#21402F] md:self-auto">
          {writing ? 'Cerrar formulario' : 'Escribir una reseña'}
        </button>
      </div>

      {writing && (
        <form onSubmit={submit} noValidate className="anim-pop mt-8 grid gap-4 rounded-[22px] bg-[#E2DDD1] p-6 md:grid-cols-[1fr_1fr_auto] md:items-start">
          <label className="text-sm font-medium">Tu nombre
            <input className="field mt-1.5" value={name} onChange={(e) => setName(e.target.value)} placeholder="Nerea Agirre" />
          </label>
          <div className="text-sm font-medium">Tu valoración
            <div className="mt-2.5 flex gap-1" role="radiogroup" aria-label="Valoración">
              {[1, 2, 3, 4, 5].map((i) => (
                <button type="button" key={i} role="radio" aria-checked={rating === i} aria-label={`${i} estrellas`} onClick={() => setRating(i)}>
                  <Star size={26} className={clsx('transition-colors', i <= rating ? 'fill-[#9A2E3D] text-[#9A2E3D]' : 'text-[#1C2326]/30')} />
                </button>
              ))}
            </div>
          </div>
          <span className="hidden md:block" />
          <label className="text-sm font-medium md:col-span-2">Tu experiencia
            <textarea className="field mt-1.5 min-h-[96px]" value={text} onChange={(e) => setText(e.target.value)} placeholder="¿Qué pediste y qué te pareció?" />
          </label>
          <button type="submit" className="btn btn-primary md:mt-7">Publicar reseña</button>
          {error && <p role="alert" className="text-sm font-medium text-[#9A2E3D] md:col-span-3">{error}</p>}
        </form>
      )}

      <div className="mt-10 grid gap-5 md:grid-cols-2 lg:grid-cols-4">
        {reviews.slice(0, 8).map((r) => (
          <article key={r.id} className="flex flex-col rounded-[22px] border border-[#1C2326]/10 bg-[#FBFBF8] p-6">
            <Stars value={r.rating} />
            <p className="mt-4 flex-1 leading-relaxed text-[#1C2326]/85">“{r.text}”</p>
            <div className="mt-5 flex items-center gap-3">
              {r.avatar
                ? <img src={IMG(r.avatar)} alt={`Foto de ${r.name}`} loading="lazy" className="img-bg h-10 w-10 rounded-full object-cover" />
                : <span className="grid h-10 w-10 place-items-center rounded-full bg-[#3E5C6B] font-semibold text-white">{r.name[0]}</span>}
              <div className="min-w-0 flex-1">
                <p className="truncate font-semibold">{r.name}</p>
                <p className="text-sm text-[#1C2326]/55">{daysAgoText(Math.floor((Date.now() - r.at) / DAY))}</p>
              </div>
              {r.mine && (
                <button onClick={() => setReviews((p) => p.filter((x) => x.id !== r.id))} aria-label="Borrar mi reseña"
                  className="grid h-9 w-9 place-items-center rounded-full text-[#1C2326]/50 hover:bg-[#9A2E3D]/10 hover:text-[#9A2E3D]">
                  <Trash2 size={16} />
                </button>
              )}
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

import { useMemo, useState } from 'react';
import { Search, Truck, CalendarCheck, PackageOpen } from 'lucide-react';
import clsx from 'clsx';
import { IMG } from '../data/images';
import { GRINDS, Grind, Product, PRODUCTS, Roast } from '../data/cafe';
import { eur } from '../lib/utils';
import Bag from './Bag';
