export default function Shop({ onAdd }: { onAdd: (l: CartLine) => void }) {
  const [q, setQ] = useState('');
  const [roast, setRoast] = useState<Roast | 'Todos'>('Todos');
  const [sort, setSort] = useState<Sort>('destacados');

  const list = useMemo(() => {
    const term = q.trim().toLowerCase();
    const out = PRODUCTS.filter((p) => (roast === 'Todos' || p.roast === roast) &&
      (!term || `${p.name} ${p.origin} ${p.notes}`.toLowerCase().includes(term)));
    if (sort === 'precio-asc') out.sort((a, b) => a.price250 - b.price250);
    if (sort === 'precio-desc') out.sort((a, b) => b.price250 - a.price250);
    return out;
  }, [q, roast, sort]);

  return (
    <div className="anim-fade">
