import { useEffect, useState } from 'react';
import { HOURS } from '../data/cafe';

const PREFIX = 'tueste-norte:';

/** Estado guardado en localStorage con valor inicial de ejemplo. */
export function usePersisted<T>(key: string, initial: T | (() => T)) {
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(PREFIX + key);
      if (raw) return JSON.parse(raw) as T;
    } catch { /* sin almacenamiento: usamos el valor de ejemplo */ }
    return typeof initial === 'function' ? (initial as () => T)() : initial;
  });
  useEffect(() => {
    try { localStorage.setItem(PREFIX + key, JSON.stringify(value)); } catch { /* ignorar */ }
  }, [key, value]);
  return [value, setValue] as const;
}

export function clearStorage() {
  try {
    Object.keys(localStorage).filter((k) => k.startsWith(PREFIX)).forEach((k) => localStorage.removeItem(k));
  } catch { /* ignorar */ }
}

export const eur = (n: number) => n.toLocaleString('es-ES', { style: 'currency', currency: 'EUR' });

export const hhmm = (min: number) => `${Math.floor(min / 60)}:${String(min % 60).padStart(2, '0')}`;

export const uid = () => Math.random().toString(36).slice(2, 8).toUpperCase();

export function hoursFor(day: number) {
  return HOURS.find((h) => h.days.includes(day))!;
}

/** "Abierto ahora · cierra a las 19:00" o cuándo vuelve a abrir. */
export function openStatus(now = new Date()) {
  const h = hoursFor(now.getDay());
  const m = now.getHours() * 60 + now.getMinutes();
  if (m >= h.open && m < h.close) return { open: true, text: `Abierto ahora · cierra a las ${hhmm(h.close)}` };
  if (m < h.open) return { open: false, text: `Cerrado · abrimos hoy a las ${hhmm(h.open)}` };
  const next = hoursFor((now.getDay() + 1) % 7);
  return { open: false, text: `Cerrado · mañana abrimos a las ${hhmm(next.open)}` };
}

/** Franjas de 30 min para reservar: desde la apertura hasta una hora antes del cierre. */
export function slotsFor(dateISO: string) {
  if (!dateISO) return [];
  const d = new Date(dateISO + 'T12:00:00');
  const h = hoursFor(d.getDay());
  const out: string[] = [];
  for (let t = h.open; t <= h.close - 60; t += 30) out.push(hhmm(t).padStart(5, '0'));
  return out;
}

export const todayISO = (offset = 0) => {
  const d = new Date();
  d.setDate(d.getDate() + offset);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export const longDate = (iso: string) =>
  new Date(iso + 'T12:00:00').toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

export const daysAgoText = (n: number) => (n === 0 ? 'hoy' : n === 1 ? 'ayer' : n < 7 ? `hace ${n} días` : n < 14 ? 'hace una semana' : `hace ${Math.round(n / 7)} semanas`);
